head.script:
scwin.trigger1_onclick = function(e) {
    log = tabControl1.getTabCount();
    //alert( tabControl1.getTabCount() );
};
scwin.trigger2_onclick = function(e) {
    tabControl1.hideTab(0);
    tabControl1.hideTab(1);
    tabControl1.hideTab(2);
};
scwin.trigger3_onclick = function(e) {
    log1 = tabControl1.getTabCount({
        hiddenTab: false
    });
    //alert( tabControl1.getTabCount({ hiddenTab : false }) );
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. Script탭 또는 Source 탭에서 scwin.trigger1_onclick 부분을 확인한다.
    //1. In the Script tab or the Source tab, check the scwin.trigger1_onclick section.
    //Test step 2. scwin.trigger2_onclick 부분을 확인한다.
    //2. Check the scwin.trigger2_onclick section.
    //Test step 3. scwin.trigger3_onclick 부분을 확인한다.
    //3. Check scwin.trigger3_onclick.
    //Test step 4. 브라우저에서 hideTab 버튼을 클릭한다.
    //4. Click the hideTab button in your browser.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. 3개의 탭이 hide 된다. (tab1 / tab2 / tab3)
    //4. Three tabs are hidden. (tab1 / tab2 / tab3)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_tab_tabs1').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_tab_tabs1').style.visibility == 'hidden'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_tab_tabs2').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_tab_tabs2').style.visibility == 'hidden'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_tab_tabs3').style.display == 'none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'tabControl1_tab_tabs3').style.visibility == 'hidden'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. tabControl1.getTabCount() 버튼을 클릭한다.
    //5. Click the tabControl1.getTabCount () button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 5. hide 처리된 탭의 갯수가 팝업으로 표시된다. (예 : '5')
    //5. hide The number of tabs processed is displayed as a popup. (E.g. '5')
    WebSquare.wUnit.addCommand("assert", "log == '5'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 6. tabControl1.getTabCount({hiddenTab:false}) 버튼을 클릭한다.
    //6. Click the tabControl1.getTabCount ({hiddenTab: false}) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 6. hide 처리된 탭을 제외한 갯수가 팝업으로 표시된다. (예 : '2')
    //6. hide The number of tabs excluding processed tabs is displayed as a popup. (E.g. '2')
    WebSquare.wUnit.addCommand("assert", "log1 == '2'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = ""; window.log1 = "";
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 21-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
